function penline(p1,p2,w) {
	noStroke();
	fill(0);
	x = p1.x;
	y = p1.y;
	d = dist(p1.x, p1.y, p2.x, p2.y);
	spacing = 2;
	steps = d/spacing;
	dx = (p2.x - p1.x)/steps;
	dy = (p2.y - p1.y)/steps;

	for(n = 0; n < steps-1; n++)
	{	
		x += dx;
		y += dy;
		wr = random(0,1)-1+w;
		vr = parseInt(random(0,10));
		if(vr)
			circle(x,y,wr);
	}
}

function drawRect(p1,width,height,w) {
	let p2 = createVector(p1.x+width,p1.y);
	let p3 = createVector(p1.x+width,p1.y+height);
	let p4 = createVector(p1.x,p1.y+height);
	fill(255);
	rect(p1.x,p1.y,width,height);
	penline(p1,p2,w);
	penline(p2,p3,w);	
	penline(p3,p4,w);	
	penline(p1,p4,w);		
}

