function hatch(p1,p2,p3,p4,w,col) {
	// p1 - p2
	//  \    \
	//   p4 - p3

	let dx = p4.x-p1.x;
	let dy = p4.y-p1.y;
	let width = p2.x-p1.x;
	let step_size = random(5,15);
	let steps = parseInt(dy / step_size);
	for(let n = 1; n < steps; n++) {

		let x = p1.x + n*(dx/steps);
		let y = p1.y + n*(dy/steps);
		let xm =  p2.x+n*(dx/steps);
		if(parseInt(random(0,5)))
		{
			let part_length = 10;
			let parts = parseInt(width/part_length);
			for(let p = 1; p<parts-1; p++)
			{
				if(!parseInt(random(0,3)))
				{
					let pS = createVector(x+part_length*p,y);
					let pE = createVector(x+part_length*(p+1),y);
					penline(pS,pE,w);
				}
			}
		}
	}
}

function drawWindows(p, b_width, b_height, ink_width) {
	let border= 10;
	let w_gap = 30;
	let h_gap = 40;
	let w_width = 5+random(0,5);
	let w_height = 10+random(0,5);
	let rows = parseInt((b_height-border*2)/h_gap);
	let cols = parseInt((b_width-border*2)/w_gap);

	for(let n = 0; n <= rows; n++)
	{
		for(let m = 0; m <= cols; m++)
		{
			let x = p.x+border+w_gap*m;
			let y = p.y+border+h_gap*n;
			let pp = createVector(x,y);
			if(random(0,2)>1 && x+w_width < p.x+b_width)
				drawRect(pp,w_width,w_height,ink_width);
		}
	}
}


